const fs = require('fs');
const TOKEN = fs.readFileSync('/tmp/owner_token.txt', 'utf8').trim();

function triggerDeploy() {
  return new Promise((resolve) => {
    const payload = JSON.stringify({ clearCache: true });
    const https = require('https');
    const req = https.request({
      hostname: 'api.ivxholding.com',
      path: '/api/ivx/deploy-tools/render/deploy',
      method: 'POST',
      headers: { 'Authorization': 'Bearer ' + TOKEN, 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(payload) }
    }, res => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try { resolve(JSON.parse(data)); } catch(e) { resolve({error: data.slice(0,300)}); }
      });
    });
    req.on('error', err => resolve({error: err.message}));
    req.write(payload);
    req.end();
  });
}

function checkVersion() {
  return new Promise((resolve) => {
    const https = require('https');
    const req = https.request({
      hostname: 'api.ivxholding.com',
      path: '/version',
      method: 'GET'
    }, res => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try { resolve(JSON.parse(data)); } catch(e) { resolve({error: data.slice(0,100)}); }
      });
    });
    req.on('error', err => resolve({error: err.message}));
    req.end();
  });
}

(async () => {
  console.log('=== TRIGGERING DEPLOY ===');
  const dep = await triggerDeploy();
  if (dep.deploy) {
    console.log('deployId:', dep.deploy.id);
    console.log('status:', dep.deploy.status);
    console.log('sha:', (dep.deploy.commitSha||'').slice(0,8));
    console.log('fail:', dep.deploy.failureReason);
  } else {
    console.log('deploy response:', JSON.stringify(dep).slice(0,400));
  }

  // Poll version every 10s for 50s
  for (let i = 1; i <= 5; i++) {
    await new Promise(r => setTimeout(r, 10000));
    const v = await checkVersion();
    console.log('poll ' + i + ':', v.commitShort, '|', v.bootTime);
    if (v.commitShort === '938b16bb') { console.log('DEPLOY_LANDED'); break; }
  }
})();
